PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        return CustomEncodableValue(SourceMsg::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 130: {
        return CustomEncodableValue(DestinationMsg::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 131: {
        return CustomEncodableValue(ImageOptionsMsg::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 132: {
        return CustomEncodableValue(VideoOptionsMsg::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 133: {
        return CustomEncodableValue(ImageCapabilitiesMsg::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(VideoCapabilitiesMsg::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(SourceMsg)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(std::any_cast<SourceMsg>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(DestinationMsg)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(std::any_cast<DestinationMsg>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ImageOptionsMsg)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(std::any_cast<ImageOptionsMsg>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(VideoOptionsMsg)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(std::any_cast<VideoOptionsMsg>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ImageCapabilitiesMsg)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<ImageCapabilitiesMsg>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(VideoCapabilitiesMsg)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<VideoCapabilitiesMsg>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

/// The codec used by MediaCompressionHostApi.
const ::flutter::StandardMessageCodec& MediaCompressionHostApi::GetCodec() {
  return ::flutter::StandardMessageCodec::GetInstance(&PigeonInternalCodecSerializer::GetInstance());
}

